--- Check for this value in `layout.orientation` to detect that the interface is in portrait orientation, upside down.
layout.portraitUpsideDown = nil

--- Check for this value in `layout.orientation` to detect that the interface is in landscape orientation, with the bottom of the device on the left.
layout.landscapeLeft = nil

--- Check for this value in `layout.orientation` to detect that the interface is in landscape orientation, with the bottom of the device on the right.
layout.landscapeRight = nil

--- This global contains the current orientation and can be one of the following: `PORTRAIT`, `PORTRAIT_UPSIDE_DOWN`, `LANDSCAPE_LEFT`, `LANDSCAPE_RIGHT`.
CurrentOrientation = nil

--- Check for this value in `CurrentOrientation` to detect if the device is in standard portrait orientation (home button at the bottom).
